</main><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>const fallback=[13.1391,123.7438];let activeLocation='pickup';const coords=(lat,lng)=>[Number(lat),Number(lng)].every(Number.isFinite)?[Number(lat),Number(lng)]:fallback;const pickupCoords=coords(document.getElementById('pickup-latitude').value,document.getElementById('pickup-longitude').value);const returnCoords=coords(document.getElementById('dropoff-latitude').value,document.getElementById('dropoff-longitude').value);const rentalMap=L.map('rental-location-map').setView(pickupCoords,13);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(rentalMap);const markers={pickup:L.marker(pickupCoords).addTo(rentalMap).bindPopup('Pick-up / Delivery'),return:L.marker(returnCoords).addTo(rentalMap).bindPopup('Drop-off / Return')};function setLocation(target,latlng){document.getElementById(target==='pickup'?'pickup-latitude':'dropoff-latitude').value=latlng.lat;document.getElementById(target==='pickup'?'pickup-longitude':'dropoff-longitude').value=latlng.lng;markers[target].setLatLng(latlng);document.getElementById(target==='pickup'?'pickup-location':'return-location').focus();}document.querySelectorAll('.location-picker-btn').forEach(button=>button.addEventListener('click',()=>{activeLocation=button.dataset.target;button.textContent='Click map now';setTimeout(()=>button.textContent='Set on map',2000);}));rentalMap.on('click',event=>setLocation(activeLocation,event.latlng));</script></body></html>
